DROP TABLE IF EXISTS `ai_call_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_call_log` (
  `log_id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `module` varchar(32) NOT NULL COMMENT '业务模块（dms/qms/pms/mms/wms/mk/hr/safety/platform）',
  `feature` varchar(64) NOT NULL COMMENT '功能标识',
  `user_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `user_name` varchar(64) DEFAULT NULL COMMENT '操作人名称',
  `status` char(1) DEFAULT '0' COMMENT '状态（0成功 1降级 2失败 3限额拦截）',
  `duration_ms` int DEFAULT NULL COMMENT '耗时（毫秒）',
  `prompt_digest` varchar(500) DEFAULT NULL,
  `error_msg` varchar(500) DEFAULT NULL COMMENT '错误信息',
  `call_time` datetime DEFAULT NULL COMMENT '调用时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`log_id`),
  KEY `idx_module_time` (`module`,`call_time`),
  KEY `idx_user_time` (`user_id`,`call_time`),
  KEY `idx_call_time` (`call_time`)
) ENGINE=InnoDB AUTO_INCREMENT=850 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI调用审计日志表';
