--
-- Table structure for table `bid_project`
--

DROP TABLE IF EXISTS `bid_project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bid_project` (
  `project_id` bigint NOT NULL AUTO_INCREMENT COMMENT '投标项目ID',
  `bid_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投标编号（TB+日期+序号）',
  `notice_id` bigint DEFAULT NULL COMMENT '关联公告ID（商机来源）',
  `project_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投标项目名称',
  `tenderee` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '招标人/采购人（冗余）',
  `agent` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '代理机构',
  `region_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '地区（行政区划码）',
  `industry` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '行业分类（字典 bid_industry）',
  `budget_amount` decimal(14,2) DEFAULT NULL COMMENT '项目预算（元）',
  `bid_amount` decimal(14,2) DEFAULT NULL COMMENT '我方报价（元）',
  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '投标状态（字典 bid_project_status）',
  `join_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '承接方式（字典 bid_join_type）',
  `partner` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联营合作方（联营时）',
  `apply_deadline` datetime DEFAULT NULL COMMENT '报名截止时间',
  `submit_deadline` datetime DEFAULT NULL COMMENT '递交截止时间',
  `open_time` datetime DEFAULT NULL COMMENT '开标时间',
  `result_time` datetime DEFAULT NULL COMMENT '结果公示时间',
  `fail_reason` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '未中标/废标原因（字典 bid_fail_reason）',
  `owner_user_id` bigint DEFAULT NULL COMMENT '投标负责人ID',
  `owner_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '负责人姓名（冗余）',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门ID',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`project_id`),
  UNIQUE KEY `uk_bid_no` (`bid_no`),
  KEY `idx_status` (`status`),
  KEY `idx_owner` (`owner_user_id`),
  KEY `idx_dept` (`dept_id`),
  KEY `idx_notice` (`notice_id`),
  KEY `idx_submit_deadline` (`submit_deadline`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='招投标-投标项目台账表';
/*!40101 SET character_set_client = @saved_cs_client */;

