--
-- Table structure for table `biz_hr_attendance_monthly`
--

DROP TABLE IF EXISTS `biz_hr_attendance_monthly`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_hr_attendance_monthly` (
  `monthly_id` bigint NOT NULL AUTO_INCREMENT COMMENT '月度ID',
  `year_month` varchar(7) NOT NULL COMMENT '年月',
  `employee_id` bigint NOT NULL COMMENT '员工ID',
  `employee_name` varchar(50) DEFAULT NULL COMMENT '员工姓名',
  `employee_no` varchar(30) DEFAULT NULL COMMENT '工号',
  `org_id` bigint DEFAULT NULL COMMENT '组织ID',
  `dept_id` bigint DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(50) DEFAULT NULL COMMENT '部门名称',
  `attend_days` decimal(5,1) DEFAULT '0.0' COMMENT '出勤天数',
  `late_count` int DEFAULT '0' COMMENT '迟到次数',
  `early_count` int DEFAULT '0' COMMENT '早退次数',
  `absent_days` decimal(5,1) DEFAULT '0.0' COMMENT '旷工天数',
  `leave_days` decimal(5,1) DEFAULT '0.0' COMMENT '请假天数',
  `outing_days` decimal(5,1) DEFAULT '0.0' COMMENT '外出天数',
  `trip_days` decimal(5,1) DEFAULT '0.0' COMMENT '出差天数',
  `required_days` decimal(5,1) DEFAULT '0.0' COMMENT '应出勤天数(排班+工作日历理论计算)',
  `actual_days` decimal(5,1) DEFAULT '0.0' COMMENT '实际工作天数(出勤+出差+外出,计薪口径)',
  `overtime_hours` decimal(6,1) DEFAULT '0.0' COMMENT '加班小时',
  `night_shift_count` int DEFAULT '0' COMMENT '夜班次数',
  `high_temp_days` decimal(5,1) DEFAULT '0.0' COMMENT '高温天数',
  `sealed_status` char(1) DEFAULT '0' COMMENT '封账状态(0未封1已封)',
  `sealed_by` varchar(64) DEFAULT NULL COMMENT '封账人',
  `sealed_time` datetime DEFAULT NULL COMMENT '封账时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`monthly_id`),
  KEY `idx_ym_emp` (`year_month`,`employee_id`)
) ENGINE=InnoDB AUTO_INCREMENT=810 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HR考勤月度汇总表';
/*!40101 SET character_set_client = @saved_cs_client */;

