DROP TABLE IF EXISTS `biz_hr_leave_balance_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_hr_leave_balance_log` (
  `log_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `balance_id` bigint NOT NULL COMMENT '假期余额ID（biz_hr_leave_balance.balance_id）',
  `leave_req_id` bigint DEFAULT NULL COMMENT '请假单ID（biz_hr_leave_request.leave_req_id）',
  `leave_req_no` varchar(64) DEFAULT NULL COMMENT '请假单号',
  `employee_id` bigint NOT NULL COMMENT '员工ID',
  `employee_name` varchar(64) DEFAULT NULL COMMENT '员工姓名',
  `leave_type` varchar(20) NOT NULL COMMENT '假别',
  `year` int NOT NULL COMMENT '年度',
  `change_days` decimal(5,1) NOT NULL COMMENT '变动天数（正数=扣减，负数=退回）',
  `before_used` decimal(5,1) DEFAULT NULL COMMENT '变动前已休天数',
  `after_used` decimal(5,1) DEFAULT NULL COMMENT '变动后已休天数',
  `before_remaining` decimal(5,1) DEFAULT NULL COMMENT '变动前剩余天数',
  `after_remaining` decimal(5,1) DEFAULT NULL COMMENT '变动后剩余天数',
  `before_frozen` decimal(5,1) DEFAULT '0.0' COMMENT '变动前冻结',
  `after_frozen` decimal(5,1) DEFAULT '0.0' COMMENT '变动后冻结',
  `change_type` varchar(20) NOT NULL DEFAULT 'deduct' COMMENT '变动类型：deduct=扣减 refund=退回 adjust=手动调整',
  `change_reason` varchar(200) DEFAULT NULL COMMENT '变动原因',
  `operator` varchar(64) DEFAULT NULL COMMENT '操作人',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`log_id`),
  KEY `idx_balance_id` (`balance_id`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_leave_req_id` (`leave_req_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='假期余额扣减明细';
