DROP TABLE IF EXISTS `biz_hr_social_security`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_hr_social_security` (
  `ss_id` bigint NOT NULL AUTO_INCREMENT COMMENT '社保ID',
  `employee_id` bigint NOT NULL COMMENT '员工ID',
  `employee_name` varchar(50) DEFAULT NULL COMMENT '员工姓名',
  `employee_no` varchar(30) DEFAULT NULL COMMENT '工号',
  `year` int NOT NULL COMMENT '年度',
  `base_amount` decimal(10,2) NOT NULL COMMENT '缴费基数',
  `plan_id` bigint DEFAULT NULL COMMENT '社保方案ID(空=用自身比例字段，兼容存量)',
  `pension_employer` decimal(8,4) DEFAULT NULL COMMENT '养老单位比例(空=继承方案)',
  `pension_employee` decimal(8,4) DEFAULT NULL COMMENT '养老个人比例(空=继承方案)',
  `medical_employer` decimal(8,4) DEFAULT NULL COMMENT '医疗单位比例(空=继承方案)',
  `medical_employee` decimal(8,4) DEFAULT NULL COMMENT '医疗个人比例(空=继承方案)',
  `unemployment_employer` decimal(8,4) DEFAULT NULL COMMENT '失业单位比例(空=继承方案)',
  `unemployment_employee` decimal(8,4) DEFAULT NULL COMMENT '失业个人比例(空=继承方案)',
  `injury_employer` decimal(8,4) DEFAULT NULL COMMENT '工伤单位比例(空=继承方案)',
  `maternity_employer` decimal(8,4) DEFAULT NULL COMMENT '生育单位比例(空=继承方案)',
  `fund_employer` decimal(8,4) DEFAULT NULL COMMENT '公积金单位比例(空=继承方案)',
  `fund_employee` decimal(8,4) DEFAULT NULL COMMENT '公积金个人比例(空=继承方案)',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门(数据权限)',
  PRIMARY KEY (`ss_id`),
  KEY `idx_emp_year` (`employee_id`,`year`),
  KEY `idx_dept_id` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=69 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HR社保公积金表';
