--
-- Table structure for table `mms_bom_detail`
--

DROP TABLE IF EXISTS `mms_bom_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mms_bom_detail` (
  `detail_id` bigint NOT NULL AUTO_INCREMENT,
  `bom_id` bigint NOT NULL,
  `seq` int DEFAULT '0' COMMENT '行序号',
  `material_id` bigint NOT NULL,
  `material_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '物料编码',
  `material_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '物料名称',
  `spec_model` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '规格型号',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '单位',
  `usage_qty` decimal(18,6) NOT NULL DEFAULT '0.000000',
  `loss_rate` decimal(6,2) DEFAULT '0.00',
  `is_key_material` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0',
  `supply_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '供应方式（字典 mms_supply_type）',
  `pick_store_id` bigint DEFAULT NULL COMMENT '默认发料仓库ID',
  `is_phantom` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '是否虚拟件(0否 1是)',
  `bom_ref_id` bigint DEFAULT NULL COMMENT '引用BOM ID(子项为半成品时关联其BOM,支持多层级展开)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建人',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新人',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`detail_id`),
  KEY `idx_bom_id` (`bom_id`),
  KEY `idx_bom_ref_id` (`bom_ref_id`)
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='BOM明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

