--
-- Table structure for table `mms_downtime`
--

DROP TABLE IF EXISTS `mms_downtime`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mms_downtime` (
  `downtime_id` bigint NOT NULL AUTO_INCREMENT,
  `downtime_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `dispatch_id` bigint DEFAULT NULL,
  `abnormal_id` bigint DEFAULT NULL COMMENT '关联异常单ID',
  `abnormal_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联异常单号(冗余)',
  `work_order_id` bigint DEFAULT NULL COMMENT '生产工单ID',
  `resource_id` bigint DEFAULT NULL,
  `resource_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '资源名称',
  `start_time` datetime NOT NULL,
  `end_time` datetime DEFAULT NULL,
  `dt_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0',
  `dt_category` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '停机分类(0=计划停机,1=非计划停机)',
  `dt_level` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '停机级别(0=一般,1=重要,2=紧急)',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '原因',
  `hours` decimal(8,2) DEFAULT NULL COMMENT '停机时长(小时)',
  `report_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '上报人',
  `handle_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '处理人',
  `handle_result` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '处理结果',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建人',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新人',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门(数据权限)',
  PRIMARY KEY (`downtime_id`),
  UNIQUE KEY `uk_downtime_no` (`downtime_no`),
  KEY `idx_abnormal_id` (`abnormal_id`),
  KEY `idx_dept_id` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='设备停机记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

