--
-- Table structure for table `mms_route_process`
--

DROP TABLE IF EXISTS `mms_route_process`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mms_route_process` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `route_id` bigint NOT NULL COMMENT '工艺路线ID',
  `process_id` bigint DEFAULT NULL COMMENT '关联工序ID(可选)',
  `process_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '工序编码',
  `process_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '工序名称',
  `process_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '工序类型',
  `workshop` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '车间',
  `line` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '产线',
  `step_seq` int NOT NULL,
  `std_time` decimal(10,2) DEFAULT '0.00' COMMENT '标准工时(秒)',
  `prep_time` decimal(10,2) DEFAULT '0.00' COMMENT '准备时间(小时)',
  `is_key_process` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '是否关键工序',
  `is_outsource` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '是否委外',
  `resource_id` bigint DEFAULT NULL COMMENT '绑定产能单元ID',
  `resource_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '产能单元名称',
  `equip_id` bigint DEFAULT NULL COMMENT '绑定设备ID',
  `equip_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '设备名称',
  `mold_id` bigint DEFAULT NULL COMMENT '模具/工装ID',
  `mold_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '模具/工装名称',
  `sop_id` bigint DEFAULT NULL COMMENT '作业指导书ID',
