CREATE TABLE `mms_work_order_bom` (
  `snapshot_id` bigint NOT NULL AUTO_INCREMENT COMMENT '快照ID',
  `work_order_id` bigint NOT NULL COMMENT '生产工单ID',
  `bom_id` bigint NOT NULL,
