--
-- Table structure for table `pms_contract`
--

DROP TABLE IF EXISTS `pms_contract`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pms_contract` (
  `contract_id` bigint NOT NULL AUTO_INCREMENT COMMENT '合同ID',
  `contract_no` varchar(64) NOT NULL COMMENT '合同编号',
  `contract_name` varchar(255) DEFAULT NULL COMMENT '合同名称',
  `order_id` bigint DEFAULT NULL COMMENT '关联采购订单ID',
  `order_no` varchar(64) DEFAULT NULL COMMENT '关联采购单号（冗余）',
  `supplier_id` bigint DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(255) DEFAULT NULL COMMENT '供应商名称（冗余）',
  `status` varchar(10) DEFAULT '0' COMMENT '状态（字典 pms_contract_status）',
  `contract_type` varchar(10) DEFAULT '0' COMMENT '合同类型（字典 pms_contract_type）',
  `sign_date` date DEFAULT NULL COMMENT '签订日期',
  `effective_date` date DEFAULT NULL COMMENT '生效日期',
  `expire_date` date DEFAULT NULL COMMENT '到期日期',
  `contract_amount` decimal(14,2) DEFAULT '0.00' COMMENT '合同金额',
  `paid_amount` decimal(14,2) DEFAULT '0.00' COMMENT '已付金额',
  `payment_terms` varchar(1000) DEFAULT NULL COMMENT '付款条款',
  `delivery_terms` varchar(1000) DEFAULT NULL COMMENT '交货条款',
  `sign_by` varchar(64) DEFAULT NULL COMMENT '签订人',
  `sign_department` varchar(128) DEFAULT NULL COMMENT '签订部门',
  `party_a` varchar(255) DEFAULT NULL COMMENT '甲方',
  `party_b` varchar(255) DEFAULT NULL COMMENT '乙方',
  `file_url` varchar(500) DEFAULT NULL COMMENT '合同附件路径',
  `file_name` varchar(200) DEFAULT NULL COMMENT '合同附件名称',
  `change_count` int DEFAULT '0' COMMENT '变更次数',
  `terminate_date` date DEFAULT NULL COMMENT '终止日期',
  `terminate_reason` varchar(500) DEFAULT NULL COMMENT '终止原因',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `audit_by` varchar(64) DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_opinion` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门(数据权限)',
  PRIMARY KEY (`contract_id`),
  UNIQUE KEY `uk_contract_no` (`contract_no`),
  KEY `idx_contract_status` (`status`),
  KEY `idx_contract_supplier` (`supplier_id`),
  KEY `idx_contract_order` (`order_id`),
  KEY `idx_dept_id` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='采购合同表';
/*!40101 SET character_set_client = @saved_cs_client */;

