DROP TABLE IF EXISTS `pms_invoice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pms_invoice` (
  `invoice_id` bigint NOT NULL AUTO_INCREMENT COMMENT '发票ID',
  `invoice_no` varchar(64) NOT NULL COMMENT '结算单号',
  `contract_id` bigint DEFAULT NULL,
  `contract_no` varchar(64) DEFAULT NULL,
  `order_id` bigint DEFAULT NULL COMMENT '采购订单ID',
  `order_no` varchar(64) DEFAULT NULL COMMENT '采购单号（冗余）',
  `supplier_id` bigint DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(255) DEFAULT NULL COMMENT '供应商名称（冗余）',
  `status` varchar(10) DEFAULT '0' COMMENT '状态（字典 pms_invoice_status）',
  `invoice_type` varchar(10) DEFAULT '0' COMMENT '发票类型（字典 pms_invoice_type）',
  `invoice_number` varchar(64) DEFAULT NULL COMMENT '发票号码',
  `invoice_date` date DEFAULT NULL COMMENT '开票日期',
  `invoice_title` varchar(255) DEFAULT NULL COMMENT '发票抬头',
  `tax_number` varchar(64) DEFAULT NULL COMMENT '税号',
  `invoice_image_url` varchar(500) DEFAULT NULL,
  `invoice_attachment` varchar(500) DEFAULT NULL,
  `invoice_amount` decimal(14,2) DEFAULT '0.00' COMMENT '不含税金额',
  `tax_amount` decimal(14,2) DEFAULT '0.00' COMMENT '税额',
  `tax_rate` decimal(10,2) DEFAULT '0.00',
  `total_amount` decimal(14,2) DEFAULT '0.00' COMMENT '价税合计',
  `payment_amount` decimal(14,2) DEFAULT '0.00' COMMENT '已付金额',
  `pay_amount` decimal(14,2) DEFAULT '0.00',
  `payment_date` date DEFAULT NULL COMMENT '付款日期',
  `payment_method` varchar(20) DEFAULT '0' COMMENT '付款方式（字典 wms_payment_method）',
  `bank_name` varchar(128) DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(64) DEFAULT NULL COMMENT '银行账号',
  `payer_bank_name` varchar(128) DEFAULT NULL COMMENT '????????????',
  `payer_bank_account` varchar(64) DEFAULT NULL COMMENT '????????????',
  `payee_name` varchar(255) DEFAULT NULL COMMENT 'payee name',
  `payee_bank_name` varchar(128) DEFAULT NULL COMMENT 'payee bank name',
  `payee_bank_account` varchar(64) DEFAULT NULL COMMENT 'payee bank account',
  `payment_remark` varchar(500) DEFAULT NULL COMMENT 'payment remark',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `audit_by` varchar(64) DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_opinion` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门(数据权限)',
  PRIMARY KEY (`invoice_id`),
  UNIQUE KEY `uk_invoice_no` (`invoice_no`),
  KEY `idx_invoice_status` (`status`),
  KEY `idx_invoice_order` (`order_id`),
  KEY `idx_invoice_supplier` (`supplier_id`),
  KEY `idx_dept_id` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='发票结算表';
/*!40101 SET character_set_client = @saved_cs_client */;

