--
-- Table structure for table `pms_purchase_order`
--

DROP TABLE IF EXISTS `pms_purchase_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pms_purchase_order` (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(64) NOT NULL COMMENT '采购单号',
  `request_id` bigint DEFAULT NULL COMMENT '关联申请ID',
  `request_no` varchar(64) DEFAULT NULL COMMENT '关联申请单号（冗余）',
  `contract_id` bigint DEFAULT NULL COMMENT '关联合同ID',
  `contract_no` varchar(64) DEFAULT NULL COMMENT '关联合同编号（冗余）',
  `supplier_id` bigint DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(255) DEFAULT NULL COMMENT '供应商名称（冗余）',
  `warehouse_id` bigint DEFAULT NULL COMMENT '目标仓库ID',
  `status` varchar(10) DEFAULT '0' COMMENT '状态（字典 pms_order_status）',
  `order_date` date DEFAULT NULL COMMENT '采购日期',
  `expect_delivery_date` date DEFAULT NULL COMMENT '预计交货日期',
  `actual_delivery_date` date DEFAULT NULL COMMENT '实际交货日期',
  `total_qty` decimal(14,2) DEFAULT '0.00' COMMENT '总数量',
  `total_amount` decimal(14,2) DEFAULT '0.00' COMMENT '总金额',
  `received_amount` decimal(14,2) DEFAULT '0.00' COMMENT '已收金额',
  `paid_amount` decimal(10,2) DEFAULT '0.00' COMMENT '??????',
  `buyer_id` bigint DEFAULT NULL COMMENT '采购员ID',
  `buyer_name` varchar(64) DEFAULT NULL COMMENT '采购员姓名（冗余）',
  `dept_id` bigint DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(128) DEFAULT NULL COMMENT '部门名称（冗余）',
  `payment_method` varchar(20) DEFAULT '0' COMMENT '付款方式（字典 wms_payment_method）',
  `payment_days` int DEFAULT '0' COMMENT '账期天数',
  `settlement_type` varchar(20) DEFAULT '0' COMMENT '结算方式（字典 wms_settlement_type）',
  `currency` varchar(10) DEFAULT 'CNY' COMMENT '结算币种（字典 wms_currency）',
  `delivery_address` varchar(500) DEFAULT NULL COMMENT '交货地址',
  `audit_by` varchar(64) DEFAULT NULL COMMENT '审批人',
  `audit_time` datetime DEFAULT NULL COMMENT '审批时间',
  `audit_opinion` varchar(500) DEFAULT NULL COMMENT '审批意见',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_order_status` (`status`),
  KEY `idx_order_supplier` (`supplier_id`),
  KEY `idx_order_buyer` (`buyer_id`),
  KEY `idx_order_request` (`request_id`),
  KEY `idx_order_date` (`order_date`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='采购订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

