DROP TABLE IF EXISTS `pms_purchase_plan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pms_purchase_plan` (
  `plan_id` bigint NOT NULL AUTO_INCREMENT COMMENT '计划ID',
  `plan_no` varchar(64) NOT NULL COMMENT '计划单号',
  `title` varchar(200) NOT NULL COMMENT '计划标题',
  `status` char(1) DEFAULT '0' COMMENT '状态（0-草稿 1-待审批 2-审批通过 3-执行中 4-已完成 5-已关闭 6-已驳回）',
  `plan_type` char(1) DEFAULT '2' COMMENT '计划类型（字典 pms_plan_type）',
  `start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `budget_amount` decimal(18,2) DEFAULT '0.00' COMMENT '预算总金额',
  `actual_amount` decimal(18,2) DEFAULT '0.00' COMMENT '实际采购金额',
  `description` text COMMENT '计划说明',
  `planner_id` bigint DEFAULT NULL COMMENT '编制人ID',
  `planner_name` varchar(64) DEFAULT NULL COMMENT '编制人姓名',
  `dept_id` bigint DEFAULT NULL COMMENT '编制部门ID',
  `dept_name` varchar(64) DEFAULT NULL COMMENT '编制部门名称',
  `audit_by` varchar(64) DEFAULT NULL COMMENT '审批人',
  `audit_time` datetime DEFAULT NULL COMMENT '审批时间',
  `audit_opinion` varchar(500) DEFAULT NULL COMMENT '审批意见',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0-正常 2-删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`plan_id`),
  UNIQUE KEY `uk_plan_no` (`plan_no`),
  KEY `idx_status` (`status`),
  KEY `idx_plan_type` (`plan_type`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='采购计划表';
/*!40101 SET character_set_client = @saved_cs_client */;

