--
-- Table structure for table `pms_receive`
--

DROP TABLE IF EXISTS `pms_receive`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pms_receive` (
  `receive_id` bigint NOT NULL AUTO_INCREMENT COMMENT '收货ID',
  `receive_no` varchar(64) NOT NULL COMMENT '收货单号',
  `order_id` bigint DEFAULT NULL COMMENT '采购订单ID',
  `order_no` varchar(64) DEFAULT NULL COMMENT '采购单号（冗余）',
  `supplier_id` bigint DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(255) DEFAULT NULL COMMENT '供应商名称（冗余）',
  `warehouse_id` bigint DEFAULT NULL COMMENT '入库仓库ID',
  `status` varchar(10) DEFAULT '0' COMMENT '状态（字典 pms_receive_status）',
  `receive_date` date DEFAULT NULL COMMENT '收货日期',
  `total_qty` decimal(14,2) DEFAULT '0.00' COMMENT '应收总数量',
  `qualified_qty` decimal(14,2) DEFAULT '0.00' COMMENT '合格数量',
  `unqualified_qty` decimal(14,2) DEFAULT '0.00' COMMENT '不合格数量',
  `inspector_id` bigint DEFAULT NULL COMMENT '验收人ID',
  `inspector_name` varchar(64) DEFAULT NULL COMMENT '验收人姓名（冗余）',
  `inbound_order_id` bigint DEFAULT NULL COMMENT '关联入库单ID',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `audit_by` varchar(64) DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_opinion` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门(数据权限)',
  PRIMARY KEY (`receive_id`),
  UNIQUE KEY `uk_receive_no` (`receive_no`),
  KEY `idx_receive_status` (`status`),
  KEY `idx_receive_order` (`order_id`),
  KEY `idx_receive_supplier` (`supplier_id`),
  KEY `idx_dept_id` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='收货验收表';
/*!40101 SET character_set_client = @saved_cs_client */;

