--
-- Table structure for table `pms_receive_detail`
--

DROP TABLE IF EXISTS `pms_receive_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pms_receive_detail` (
  `detail_id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `receive_id` bigint NOT NULL COMMENT '收货ID',
  `order_detail_id` bigint DEFAULT NULL COMMENT '订单明细ID',
  `material_id` bigint DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) DEFAULT NULL COMMENT '物料编码（冗余）',
  `material_name` varchar(255) DEFAULT NULL COMMENT '物料名称（冗余）',
  `spec_model` varchar(255) DEFAULT NULL COMMENT '规格型号（冗余）',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位（冗余）',
  `receive_qty` decimal(14,2) DEFAULT NULL COMMENT '应收数量',
  `qualified_qty` decimal(14,2) DEFAULT NULL COMMENT '合格数量',
  `unqualified_qty` decimal(14,2) DEFAULT NULL COMMENT '不合格数量',
  `unit_price` decimal(14,2) DEFAULT NULL COMMENT '单价',
  `amount` decimal(14,2) DEFAULT NULL COMMENT '金额',
  `batch_no` varchar(64) DEFAULT NULL COMMENT '批次号',
  `production_date` date DEFAULT NULL COMMENT '生产日期',
  `expiry_date` date DEFAULT NULL COMMENT '保质期至',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`detail_id`),
  KEY `idx_recv_detail_receive` (`receive_id`),
  KEY `idx_recv_detail_material` (`material_id`)
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='收货验收明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

