DROP TABLE IF EXISTS `qms_gauge`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qms_gauge` (
  `gauge_id` bigint NOT NULL AUTO_INCREMENT COMMENT '量检具ID',
  `gauge_no` varchar(64) NOT NULL COMMENT '量检具编号',
  `gauge_name` varchar(128) NOT NULL COMMENT '量检具名称',
  `gauge_type` varchar(64) DEFAULT NULL COMMENT '量检具类型',
  `precision_val` varchar(64) DEFAULT NULL COMMENT '精度',
  `measure_range` varchar(128) DEFAULT NULL COMMENT '测量范围',
  `calib_cycle` int DEFAULT NULL COMMENT '校准周期（月）',
  `last_calib_date` date DEFAULT NULL COMMENT '上次校准日期',
  `next_calib_date` date DEFAULT NULL COMMENT '下次校准日期',
  `gauge_status` varchar(10) DEFAULT '0' COMMENT '量检具状态（字典 qms_gauge_status）',
  `dept_id` bigint DEFAULT NULL COMMENT '使用部门ID',
  `status` char(1) DEFAULT '0' COMMENT '状态（字典 qms_gauge_status）',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`gauge_id`),
  UNIQUE KEY `uk_gauge_no` (`gauge_no`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='量检具台账表';
