  `sample_seq` int DEFAULT NULL COMMENT '抽样序号',
  `measured_val` varchar(255) DEFAULT NULL COMMENT '实测值',
  `item_result` varchar(10) DEFAULT NULL COMMENT '单项判定（1合格 2不合格）',
