  `defect_code` varchar(64) DEFAULT NULL COMMENT '不良代码（不合格时）',
  `defect_name` varchar(128) DEFAULT NULL COMMENT '不良名称（冗余）',
  `defect_level` varchar(10) DEFAULT NULL COMMENT '缺陷等级（1致命 2严重 3一般 4轻微）',
  `defect_qty` int DEFAULT '0' COMMENT '缺陷数量（该缺陷出现的次数）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`item_id`),
  KEY `idx_item_task` (`task_id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='检验单项实测表';
