--
-- Table structure for table `qms_insp_task`
--

DROP TABLE IF EXISTS `qms_insp_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qms_insp_task` (
  `task_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `task_no` varchar(64) NOT NULL COMMENT '任务编号',
  `task_type` varchar(10) NOT NULL COMMENT '检验类型（IQC/IPQC/FQC/OQC）',
  `source_type` varchar(32) DEFAULT NULL COMMENT '来源类型（字典 qms_source_type）',
  `source_no` varchar(64) DEFAULT NULL COMMENT '来源单号',
  `material_id` bigint DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) DEFAULT NULL COMMENT '物料编码（冗余）',
  `material_name` varchar(255) DEFAULT NULL COMMENT '物料名称（冗余）',
  `supplier_id` bigint DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(255) DEFAULT NULL COMMENT '供应商名称（冗余）',
  `batch_no` varchar(64) DEFAULT NULL COMMENT '批次号',
  `inspect_qty` decimal(18,4) DEFAULT NULL COMMENT '送检数量',
  `aql_level` varchar(10) DEFAULT NULL COMMENT 'AQL等级',
  `inspect_level` varchar(10) DEFAULT '1' COMMENT '检验严格度（字典 qms_inspect_level）',
  `inspect_method` varchar(10) DEFAULT 'II' COMMENT 'inspect level',
  `sample_size` int DEFAULT NULL COMMENT '样本量(n)',
  `ac_val` int DEFAULT NULL COMMENT '接收数(Ac)',
  `re_val` int DEFAULT NULL COMMENT '拒收数(Re)',
  `task_status` varchar(10) DEFAULT '0' COMMENT '任务状态（字典 qms_task_status）',
  `inspect_result` varchar(10) DEFAULT NULL COMMENT '检验结果（1合格 2不合格）',
  `defect_level` varchar(10) DEFAULT NULL COMMENT '最高缺陷等级（字典 qms_defect_level）',
  `inspector_id` bigint DEFAULT NULL COMMENT '检验员ID',
  `inspector_name` varchar(64) DEFAULT NULL COMMENT '检验员名称',
  `inspect_time` datetime DEFAULT NULL COMMENT '检验时间',
  `judge_time` datetime DEFAULT NULL COMMENT '判定时间',
  `gauge_id` bigint DEFAULT NULL COMMENT '使用量检具ID',
  `gauge_name` varchar(128) DEFAULT NULL COMMENT '量检具名称（冗余）',
  `gauge_no` varchar(64) DEFAULT NULL COMMENT '量检具编号（冗余）',
  `is_recheck` char(1) DEFAULT '0' COMMENT '是否复检（0否 1是）',
  `origin_task_id` bigint DEFAULT NULL COMMENT '原任务ID（复检时关联）',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门(数据权限)',
  PRIMARY KEY (`task_id`),
  UNIQUE KEY `uk_task_no` (`task_no`),
  KEY `idx_task_type` (`task_type`),
  KEY `idx_task_status` (`task_status`),
  KEY `idx_task_material` (`material_id`),
  KEY `idx_task_source` (`source_type`,`source_no`),
  KEY `idx_dept_id` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='检验任务表';
/*!40101 SET character_set_client = @saved_cs_client */;

