DROP TABLE IF EXISTS `qms_inspect_std`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qms_inspect_std` (
  `std_id` bigint NOT NULL AUTO_INCREMENT COMMENT '标准ID',
  `std_code` varchar(64) NOT NULL COMMENT '标准编码',
  `std_name` varchar(128) NOT NULL COMMENT '检验项目名称',
  `inspect_method` varchar(255) DEFAULT NULL COMMENT '检验方法',
  `unit` varchar(32) DEFAULT NULL COMMENT '计量单位',
  `val_min` decimal(18,4) DEFAULT NULL COMMENT '标准下限',
  `val_max` decimal(18,4) DEFAULT NULL COMMENT '标准上限',
  `target_val` decimal(18,4) DEFAULT NULL COMMENT '目标值',
  `judge_rule` varchar(10) DEFAULT '1' COMMENT '判定规则（字典 qms_judge_rule）',
  `industry_type` varchar(32) DEFAULT NULL COMMENT '行业类型（字典 qms_industry_type）',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`std_id`),
  UNIQUE KEY `uk_std_code` (`std_code`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='检验标准库表';
/*!40101 SET character_set_client = @saved_cs_client */;

