--
-- Table structure for table `qms_lot_genealogy`
--

DROP TABLE IF EXISTS `qms_lot_genealogy`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qms_lot_genealogy` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '投入批次号（原料/半成品）；NULL=该事件无投入侧',
  `child_batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '产出批次号（半成品/成品，NULL=断点未登记）',
  `work_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生产工单号',
  `op_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '工序ID',
  `op_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '工序名称',
  `material_id` bigint DEFAULT NULL COMMENT '物料ID（复用仓库主数据）',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '物料名称',
  `qty_in` decimal(18,4) DEFAULT NULL COMMENT '投入数量',
  `qty_out` decimal(18,4) DEFAULT NULL COMMENT '产出数量',
  `line_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '产线ID',
  `line_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '产线名称',
  `operator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作员',
  `supplier_id` bigint DEFAULT NULL COMMENT '供应商ID（原料批次关联）',
  `supplier_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '供应商名称',
  `source_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'manual' COMMENT '来源（feeding=投料, report=报工, complete=完工, transfer=调拨, rework=返工, merge=合并, split=拆分, manual=补录）',
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '鏉ユ簮鍗曟嵁鍙凤紙骞傜瓑閿?紝濡傞?鏂欏崟鍙?鏄庣粏搴忓彿/瀹屽伐鍏ュ簱鍗曞彿锛',
  `trace_time` datetime DEFAULT NULL COMMENT '谱系时间',
  `break_flag` tinyint DEFAULT '0' COMMENT '断点标记（0=正常 1=断点）',
  `break_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '断点原因',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_parent_batch` (`parent_batch_no`),
  KEY `idx_child_batch` (`child_batch_no`),
  KEY `idx_work_order` (`work_order_no`),
  KEY `idx_genealogy_parent_batch` (`parent_batch_no`),
  KEY `idx_genealogy_child_batch` (`child_batch_no`),
  KEY `idx_genealogy_source` (`source_type`,`source_no`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='批次谱系表';
/*!40101 SET character_set_client = @saved_cs_client */;

