--
-- Table structure for table `qms_material_attr`
--

DROP TABLE IF EXISTS `qms_material_attr`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qms_material_attr` (
  `attr_id` bigint NOT NULL AUTO_INCREMENT COMMENT '属性ID',
  `material_id` bigint NOT NULL COMMENT '物料ID（关联WMS物料主数据）',
  `material_code` varchar(64) DEFAULT NULL COMMENT '物料编码（冗余）',
  `material_name` varchar(255) DEFAULT NULL COMMENT '物料名称（冗余）',
  `inspect_types` varchar(64) DEFAULT NULL COMMENT '检验类型（多选逗号分隔：IQC,IPQC,FQC,OQC）',
  `industry_type` varchar(32) DEFAULT NULL COMMENT '行业类型（字典 qms_industry_type）',
  `is_exempt` char(1) DEFAULT '0' COMMENT '是否免检（0否 1是）',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`attr_id`),
  UNIQUE KEY `uk_material_id` (`material_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='物料质量属性表';
/*!40101 SET character_set_client = @saved_cs_client */;

