  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`action_id`),
  KEY `idx_mr_id` (`mr_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='管理评审改进项表';
