CREATE TABLE `qms_ncr` (
  `ncr_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'NCR ID',
  `ncr_no` varchar(64) NOT NULL COMMENT 'NCR编号',
  `source_type` varchar(32) DEFAULT NULL COMMENT '来源类型（inspection/complaint/patrol）',
  `source_id` bigint DEFAULT NULL COMMENT '来源ID',
  `source_no` varchar(64) DEFAULT NULL COMMENT '来源单号',
  `task_id` bigint DEFAULT NULL COMMENT '检验任务ID',
  `material_id` bigint DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) DEFAULT NULL COMMENT '物料编码（冗余）',
  `material_name` varchar(255) DEFAULT NULL COMMENT '物料名称（冗余）',
