  `resp_dept_name` varchar(128) DEFAULT NULL COMMENT '责任部门名称',
  `verify_result` varchar(10) DEFAULT NULL COMMENT '验证结果（1通过 2不通过）',
  `verify_remark` varchar(500) DEFAULT NULL COMMENT '验证说明',
  `verifier_id` bigint DEFAULT NULL COMMENT '验证人ID',
  `verifier_name` varchar(64) DEFAULT NULL COMMENT '验证人名称',
  `verify_time` datetime DEFAULT NULL COMMENT '验证时间',
  `close_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `dispose_qty` decimal(18,4) DEFAULT NULL COMMENT 'dispose qty',
  `dispose_remark` varchar(500) DEFAULT NULL COMMENT 'dispose remark',
  `status` char(1) DEFAULT '0' COMMENT '状态（字典 qms_ncr_status）',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门(数据权限)',
  PRIMARY KEY (`ncr_id`),
  UNIQUE KEY `uk_ncr_no` (`ncr_no`),
  KEY `idx_ncr_status` (`ncr_status`),
  KEY `idx_ncr_material` (`material_id`),
  KEY `idx_ncr_source` (`source_type`,`source_no`),
  KEY `idx_dept_id` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='不合格品报告表';
