INSERT INTO `sys_config` VALUES (1,'主框架页-默认皮肤样式名称','sys.index.skinName','skin-blue','Y','admin','2026-07-13 11:25:53','',NULL,'蓝色 skin-blue、绿色 skin-green、紫色 skin-purple、红色 skin-red、黄色 skin-yellow'),(2,'用户管理-账号初始密码','sys.user.initPassword','123456','Y','admin','2026-07-13 11:25:53','',NULL,'初始化密码 123456'),(3,'主框架页-侧边栏主题','sys.index.sideTheme','theme-dark','Y','admin','2026-07-13 11:25:53','',NULL,'深色主题theme-dark，浅色主题theme-light'),(4,'账号自助-验证码开关','sys.account.captchaEnabled','false','Y','admin','2026-07-13 11:25:53','',NULL,'是否开启验证码功能（true开启，false关闭）'),(5,'账号自助-是否开启用户注册功能','sys.account.registerUser','false','Y','admin','2026-07-13 11:25:53','',NULL,'是否开启注册用户功能（true开启，false关闭）'),(6,'用户登录-黑名单列表','sys.login.blackIPList','','Y','admin','2026-07-13 11:25:53','',NULL,'设置登录IP黑名单限制，多个匹配项以;分隔，支持匹配（*通配、网段）'),(7,'用户管理-初始密码修改策略','sys.account.initPasswordModify','1','Y','admin','2026-07-13 11:25:53','',NULL,'0：初始密码修改策略关闭，没有任何提示，1：提醒用户，如果未修改初始密码，则在登录时就会提醒修改密码对话框'),(8,'用户管理-账号密码更新周期','sys.account.passwordValidateDays','0','Y','admin','2026-07-13 11:25:53','',NULL,'密码更新周期（填写数字，数据初始化值为0不限制，若修改必须为大于0小于365的正整数），如果超过这个周期登录系统时，则在登录时就会提醒修改密码对话框'),(9,'用户管理-密码字符范围','sys.account.chrtype','0','Y','admin','2026-07-13 11:25:53','',NULL,'默认任意字符范围，0任意（密码可以输入任意字符），1数字（密码只能为0-9数字），2英文字母（密码只能为a-z和A-Z字母），3字母和数字（密码必须包含字母，数字）,4字母数字和特殊字符（目前支持的特殊字符包括：~!@#$%^&*()-=_+）'),(104,'AI智能报修开关','dms.ai.repair_assistant','true','Y','admin','2026-07-17 08:29:53','admin','2026-09-15 16:04:48','智能报修助手开关'),(105,'AI智能派工开关','dms.ai.dispatch_recommend','true','Y','admin','2026-07-17 08:29:53','admin','2026-09-15 16:04:48','智能派工推荐开关'),(106,'AI知识问答开关','dms.ai.knowledge_qa','true','Y','admin','2026-07-17 08:29:53','admin','2026-09-15 16:04:48','维修知识问答开关'),(108,'是否启用企业信息查询','pms.enterprise.lookup.enabled','true','Y','admin','2026-07-27 18:35:30','admin','2026-07-27 23:18:41','企业信息查询功能开关'),(109,'企业查询API提供商','pms.enterprise.lookup.provider','qichacha','Y','admin','2026-07-27 18:35:30','admin','2026-07-27 23:18:41','tianyancha=天眼查 qichacha=企查查 custom=自定义'),(110,'企业查询API地址','pms.enterprise.lookup.api.url','https://api.qichacha.com/ECIV4/GetBasicDetailsByName','Y','admin','2026-07-27 18:35:30','admin','2026-07-27 23:18:41','第三方企业信息API地址'),(111,'企业查询API密钥','pms.enterprise.lookup.api.key','54038e1f62134e74bcdbc874bda6e480','Y','admin','2026-07-27 18:35:30','admin','2026-07-27 23:18:41','第三方企业信息API密钥'),(112,'企业查询API Secret','pms.enterprise.lookup.api.secret','674903BC12103F7C1D50FCF9C4C358E7','Y','admin','2026-07-27 21:02:40','',NULL,NULL),(114,'系统安全-页面水印开关','sys.index.watermarkEnabled','true','Y','admin','2026-09-09 17:14:59','admin','2026-09-09 17:43:07','是否启用页面水印功能（true开启，false关闭），开启后所有页面显示当前用户名水印'),(115,'系统安全-多终端登录开关','sys.login.multiLoginEnabled','true','Y','admin','2026-09-09 17:35:38','',NULL,'是否允许同一账号多终端同时登录（true允许，false不允许，不允许时新登录会踢出旧会话）'),(116,'系统安全-会话超时时长','sys.token.expireTime','120','Y','admin','2026-09-09 17:35:41','',NULL,'令牌有效期（分钟），默认120分钟=2小时，活跃用户自动续期。修改后需刷新缓存生效'),(117,'AI功能总开关','ai.enabled','true','Y','admin','2026-09-15 16:54:46','admin','2026-09-18 21:17:01','从dms.ai.enabled平移'),(118,'AI大模型API地址','ai.api_url','https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions','Y','admin','2026-09-15 16:54:46','admin','2026-09-18 21:17:01','从dms.ai.api_url平移'),(119,'AI大模型API密钥','ai.api_key','ENC:6d6It9PakGs/GZQqScQlAPHwahRYZXOut3yrBmSkkXR0kp7Xt24VMtPi+M0pK1+c6XVa78txDQXZUVC+7nnH5/AYkKgJa1lHfOyao4q8ghrprPVA6G45ieKrb56YQ+ou5Q8Fa3lAnvj7qPn7gdLdJIVH0iJuCSiRaxjpy496fsQ=','Y','admin','2026-09-15 16:54:46','system','2026-10-12 20:12:01','从dms.ai.api_key平移'),(120,'AI大模型名称','ai.model_name','qwen-plus','Y','admin','2026-09-15 16:54:46','admin','2026-09-18 21:17:01','从dms.ai.model_name平移'),(121,'AI月度调用上限','ai.monthly_limit','10000','Y','admin','2026-09-15 16:54:46','admin','2026-09-18 21:17:01','AI月度调用次数上限（原100，2026-09-17调至10000）'),(122,'AI Embedding API地址','ai.embedding_url','https://dashscope.aliyuncs.com/compatible-mode/v1/embeddings','Y','admin','2026-09-15 18:43:53','admin','2026-09-18 21:17:01','RAG向量化用，未配置时降级关键词检索'),(123,'AI Embedding API密钥','ai.embedding_key','ENC:6d6It9PakGs/GZQqScQlAPHwahRYZXOut3yrBmSkkXR0kp7Xt24VMtPi+M0pK1+c6XVa78txDQXZUVC+7nnH5/AYkKgJa1lHfOyao4q8ghrprPVA6G45ieKrb56YQ+ou5Q8Fa3lAnvj7qPn7gdLdJIVH0iJuCSiRaxjpy496fsQ=','Y','admin','2026-09-15 18:43:53','system','2026-10-12 20:12:01','留空时沿用对话模型密钥'),(124,'AI Embedding模型名','ai.embedding_model','text-embedding-v3','Y','admin','2026-09-15 18:43:53','admin','2026-09-18 21:17:01','如 text-embedding-v3 / embedding-3'),(125,'NL2Query功能开关','ai.nl2query.enabled','true','Y','admin','2026-09-15 19:09:56','admin','2026-09-18 21:17:01','自然语言查数开关，默认关闭，开启前需配置白名单表'),(128,'知识库直接命中开关','ai.knowledge.direct_hit','true','Y','admin','2026-09-16 16:44:53','',NULL,'高置信命中时直接返回知识库原文，跳过大模型（大幅提速）'),(131,'NL2Query黑名单表','ai.nl2query.blockedTables','biz_hr_payslip,biz_hr_payroll_batch,biz_hr_tax_rate,biz_hr_salary_item,biz_hr_salary_plan,biz_hr_ss_plan,biz_hr_social_security,biz_hr_special_deduction,biz_hr_leave_balance,sys_config,openapi_app','Y','admin','2026-09-17 18:50:25','admin','2026-09-17 19:29:17','智能查询禁止访问的表，逗号分隔，优先级最高'),(132,'文件上传根目录','system.upload.path','D:/ruoyi/uploadPath','Y','admin','2026-09-20 22:19:26','system','2026-09-20 22:36:23','文件上传根目录（优先级：环境变量 EDOP_UPLOAD_PATH > 本项 > application.yml）');
