INSERT INTO `sys_notice` VALUES (1,'温馨提醒：2018-07-01 若依新版本发布啦','2',_binary '新版本内容','0','admin','2026-07-13 11:25:53','',NULL,'管理员'),(2,'维护通知：2018-07-01 若依系统凌晨维护','1',_binary '维护内容','0','admin','2026-07-13 11:25:53','',NULL,'管理员'),(3,'若依开源框架介绍','1',_binary '<p><span style=\"color: rgb(230, 0, 0);\">项目介绍</span></p><p><font color=\"#333333\">RuoYi开源项目是为企业用户定制的后台脚手架框架，为企业打造的一站式解决方案，降低企业开发成本，提升开发效率。主要包括用户管理、角色管理、部门管理、菜单管理、参数管理、字典管理、</font><span style=\"color: rgb(51, 51, 51);\">岗位管理</span><span style=\"color: rgb(51, 51, 51);\">、定时任务</span><span style=\"color: rgb(51, 51, 51);\">、</span><span style=\"color: rgb(51, 51, 51);\">服务监控、登录日志、操作日志、代码生成等功能。其中，还支持多数据源、数据权限、国际化、Redis缓存、Docker部署、滑动验证码、第三方认证登录、分布式事务、</span><font color=\"#333333\">分布式文件存储</font><span style=\"color: rgb(51, 51, 51);\">、分库分表处理等技术特点。</span></p><p><img src=\"https://foruda.gitee.com/images/1773931848342439032/a4d22313_1815095.png\" style=\"width: 64px;\"><br></p><p><span style=\"color: rgb(230, 0, 0);\">官网及演示</span></p><p><span style=\"color: rgb(51, 51, 51);\">若依官网地址：&nbsp;</span><a href=\"http://ruoyi.vip\" target=\"_blank\">http://ruoyi.vip</a><a href=\"http://ruoyi.vip\" target=\"_blank\"></a></p><p><span style=\"color: rgb(51, 51, 51);\">若依文档地址：&nbsp;</span><a href=\"http://doc.ruoyi.vip\" target=\"_blank\">http://doc.ruoyi.vip</a><br></p><p><span style=\"color: rgb(51, 51, 51);\">演示地址【不分离版】：&nbsp;</span><a href=\"http://demo.ruoyi.vip\" target=\"_blank\">http://demo.ruoyi.vip</a></p><p><span style=\"color: rgb(51, 51, 51);\">演示地址【分离版本】：&nbsp;</span><a href=\"http://vue.ruoyi.vip\" target=\"_blank\">http://vue.ruoyi.vip</a></p><p><span style=\"color: rgb(51, 51, 51);\">演示地址【微服务版】：&nbsp;</span><a href=\"http://cloud.ruoyi.vip\" target=\"_blank\">http://cloud.ruoyi.vip</a></p><p><span style=\"color: rgb(51, 51, 51);\">演示地址【移动端版】：&nbsp;</span><a href=\"http://h5.ruoyi.vip\" target=\"_blank\">http://h5.ruoyi.vip</a></p><p><br style=\"color: rgb(48, 49, 51); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px;\"></p>','0','admin','2026-07-13 11:25:53','',NULL,'管理员'),(10,'PM维护提醒','1',_binary 'PM计划「4」已生成工单「WO202607170007」\n关联设备：立式铣床\n下次执行时间：Sun Aug 16 08:02:04 CST 2026','0','system','2026-07-17 08:02:04','',NULL,NULL),(11,'工单派工通知','1',_binary '工单「WO202607160003」已派工给您，设备：数控加工中心，请及时接单处理。','0','system','2026-07-17 09:16:13','',NULL,NULL),(12,'报修确认通知','1',_binary '您的报修工单「WO202607160003」已被维修员「李华」接单，正在处理中。','0','system','2026-07-17 09:16:16','',NULL,NULL),(13,'新工单通知','1',_binary '新工单「WO202607170008」已创建，设备：平面磨床，优先级：中，请尽快派工处理。','0','system','2026-07-17 09:20:13','',NULL,NULL),(14,'工单派工通知','1',_binary '工单「WO202607170008」已派工给您，设备：平面磨床，请及时接单处理。','0','system','2026-07-17 09:20:53','',NULL,NULL),(15,'工单改派通知','1',_binary '工单「WO202607170008」已改派给您，设备：平面磨床，请及时接单处理。','0','system','2026-07-17 09:21:01','',NULL,NULL),(16,'报修确认通知','1',_binary '您的报修工单「WO202607170008」已被维修员「李华」接单，正在处理中。','0','system','2026-07-17 09:21:03','',NULL,NULL),(17,'新工单通知','1',_binary '新工单「WO202607170009」已创建，优先级：高，请尽快派工处理。','0','system','2026-07-17 14:58:38','',NULL,NULL),(18,'新工单通知','1',_binary '新工单「WO202607170010」已创建，设备：EQ005 - 数控加工中心，优先级：高，请尽快派工处理。','0','system','2026-07-17 15:07:15','',NULL,NULL),(19,'新工单通知','1',_binary '新工单「WO202607170011」已创建，设备：EQ004 - 平面磨床、EQ002 - 立式铣床，优先级：高，请尽快派工处理。','0','system','2026-07-17 15:11:24','',NULL,NULL),(20,'新工单通知','1',_binary '新工单「WO202607170012」已创建，设备：EQ005 - 数控加工中心、EQ004 - 平面磨床，优先级：高，请尽快派工处理。','0','system','2026-07-17 15:42:07','',NULL,NULL),(21,'工单SLA超时升级通知','1',_binary '工单「WO202607170012」响应超时！，设备：EQ005 - 数控加工中心、EQ004 - 平面磨床，优先级：高，请立即处理。','0','system','2026-07-17 17:00:00','',NULL,NULL),(22,'新工单通知','1',_binary '新工单「WO202607170013」已创建，设备：空压机1，优先级：中，请尽快派工处理。','0','system','2026-07-17 17:51:35','',NULL,NULL),(23,'新工单通知','1',_binary '新工单「WO202607170014」已创建，设备：AirCompressor1，优先级：中，请尽快派工处理。','0','system','2026-07-17 18:08:35','',NULL,NULL),(24,'工单派工通知','1',_binary '工单「WO202607170014」已派工给您，设备：AirCompressor1，请及时接单处理。','0','system','2026-07-17 18:09:0