/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_wms_inbound_order_dept` BEFORE INSERT ON `wms_inbound_order` FOR EACH ROW BEGIN IF NEW.dept_id IS NULL AND NEW.create_by IS NOT NULL THEN SET NEW.dept_id = (SELECT u.dept_id FROM sys_user u WHERE u.user_name = NEW.create_by LIMIT 1); END IF; END */;;
