--
-- Table structure for table `wms_supplier`
--

DROP TABLE IF EXISTS `wms_supplier`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wms_supplier` (
  `supplier_id` bigint NOT NULL AUTO_INCREMENT COMMENT '供应商ID',
  `supplier_code` varchar(64) NOT NULL COMMENT '供应商编码',
  `supplier_name` varchar(255) NOT NULL COMMENT '供应商名称',
  `supplier_short_name` varchar(128) DEFAULT NULL COMMENT '供应商简称',
  `supplier_type` varchar(20) DEFAULT '0' COMMENT '供应商类型',
  `supplier_level` varchar(10) DEFAULT NULL COMMENT '供应商等级',
  `unified_credit_code` varchar(64) DEFAULT NULL COMMENT '统一社会信用代码',
  `contact_person` varchar(64) DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `email` varchar(128) DEFAULT NULL COMMENT '邮箱',
  `fax` varchar(20) DEFAULT NULL COMMENT '传真',
  `website` varchar(255) DEFAULT NULL COMMENT '网址',
  `postcode` varchar(10) DEFAULT NULL COMMENT '邮政编码',
  `address` varchar(500) DEFAULT NULL COMMENT '地址',
  `legal_person` varchar(64) DEFAULT NULL COMMENT '法人代表',
  `registered_capital` decimal(18,2) DEFAULT '0.00' COMMENT '注册资本（万元）',
  `enterprise_nature` varchar(20) DEFAULT NULL COMMENT '企业性质',
  `business_scope` varchar(1000) DEFAULT NULL COMMENT '经营范围',
  `established_date` date DEFAULT NULL COMMENT '成立日期',
  `bank_name` varchar(128) DEFAULT NULL COMMENT '开户银行',
  `bank_branch` varchar(128) DEFAULT NULL COMMENT '开户支行',
  `bank_account` varchar(64) DEFAULT NULL COMMENT '银行账号',
  `tax_number` varchar(64) DEFAULT NULL COMMENT '税号',
  `invoice_title` varchar(255) DEFAULT NULL COMMENT '发票抬头',
  `invoice_address` varchar(500) DEFAULT NULL COMMENT '发票地址',
  `invoice_phone` varchar(20) DEFAULT NULL COMMENT '发票联系电话',
  `payment_method` varchar(20) DEFAULT '0' COMMENT '付款方式',
  `payment_days` int DEFAULT '0' COMMENT '账期天数',
  `settlement_type` varchar(20) DEFAULT '0' COMMENT '结算方式',
  `currency` varchar(10) DEFAULT 'CNY' COMMENT '结算币种',
  `delivery_cycle` int DEFAULT NULL COMMENT '交货周期',
  `min_order_amount` decimal(18,2) DEFAULT '0.00' COMMENT '最小订单金额',
  `cooperation_date` date DEFAULT NULL COMMENT '合作开始日期',
  `qualification_status` char(1) DEFAULT '0' COMMENT '资质状态',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`supplier_id`),
  UNIQUE KEY `uk_supplier_code` (`supplier_code`),
  KEY `idx_supplier_type` (`supplier_type`),
  KEY `idx_supplier_level` (`supplier_level`),
  KEY `idx_unified_credit_code` (`unified_credit_code`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='供应商表';
/*!40101 SET character_set_client = @saved_cs_client */;

